fn to_tv_fp(x: G) -> Fp {
    Fp::from_canonical(x.to_canonical_u64()).expect("canonical Goldilocks element")
}

fn to_tv_fp2(x: F) -> Fp2 {
    let [c0, c1] = x.coeffs();
    Fp2::new(to_tv_fp(c0), to_tv_fp(c1))
}

fn to_tv_fp2s(xs: &[F]) -> Vec<Fp2> {
    xs.iter().copied().map(to_tv_fp2).collect()
}

fn eval_mle_i64(col: &[i64], point: &[Fp2]) -> Fp2 {
    col.iter().enumerate().fold(Fp2::ZERO, |acc, (row, &v)| {
        let eq = point.iter().enumerate().fold(Fp2::ONE, |w, (bit, &r)| {
            w * if (row >> bit) & 1 == 0 {
                Fp2::ONE - r
            } else {
                r
            }
        });
        acc + eq * to_tv_fp2(F::from(G::from_i64(v)))
    })
}

fn eval_mle_fp(col: &[G], point: &[Fp2]) -> Fp2 {
    col.iter().enumerate().fold(Fp2::ZERO, |acc, (row, &v)| {
        let eq = point.iter().enumerate().fold(Fp2::ONE, |w, (bit, &r)| {
            w * if (row >> bit) & 1 == 0 {
                Fp2::ONE - r
            } else {
                r
            }
        });
        acc + eq * Fp2::from(to_tv_fp(v))
    })
}

fn eq_ext(point: &[F], row: usize) -> F {
    point.iter().enumerate().fold(F::ONE, |acc, (bit, &r)| {
        acc * if (row >> bit) & 1 == 0 { F::ONE - r } else { r }
    })
}

fn fresh_transcripts() -> (Transcript, tv_hash::transcript::Transcript) {
    let statement = [0x11; 32];
    let session = [0x22; 16];
    let prover = Transcript::new(&SessionContext {
        protocol: Ascii::new("tessera-protocol/1").unwrap(),
        mode: Mode::NonInteractive,
        params: ParamSetId(Ascii::new("test-small/1").unwrap()),
        statement_digest: statement,
        session_id: session,
    });
    let verifier = tv_hash::transcript::Transcript::new(&tv_hash::transcript::SessionContext {
        protocol: tv_hash::transcript::Ascii::new("tessera-protocol/1").unwrap(),
        mode: tv_hash::transcript::Mode::NonInteractive,
        params: tv_hash::transcript::ParamSetId(
            tv_hash::transcript::Ascii::new("test-small/1").unwrap(),
        ),
        statement_digest: statement,
        session_id: session,
    });
    (prover, verifier)
}

fn sample_point(n_vars: usize, seed: u64) -> Vec<Fp2> {
    (0..n_vars)
        .map(|i| {
            Fp2::new(
                Fp::from_canonical(seed.wrapping_add((i as u64 + 1) * 17)).unwrap(),
                Fp::from_canonical(seed.wrapping_add((i as u64 + 1) * 31)).unwrap(),
            )
        })
        .collect()
}

fn base_claims() -> ClaimList {
    let raw: Value = serde_json::from_str(include_str!(
        "../../../spec/vectors/claims/claim-lists.json"
    ))
    .unwrap();
    let hex_str = raw["cases"]
        .as_array()
        .unwrap()
        .iter()
        .find(|c| c["model"] == "tiny-2-servable.d")
        .unwrap()["hex"]
        .as_str()
        .unwrap();
    let bytes: Vec<u8> = hex_str
        .as_bytes()
        .chunks_exact(2)
        .map(|s| u8::from_str_radix(std::str::from_utf8(s).unwrap(), 16).unwrap())
        .collect();
    ClaimList::open(&bytes, &DecodeLimits::MESSAGE).unwrap()
}

fn model_with_requant_budget(max_log2_rows: u8, shifts: &[i8]) -> (ClaimList, lowering::Graph) {
    let mut claims = base_claims();
    claims.arch.d_model = 2;
    claims.arch.n_heads = 1;
    claims.arch.n_kv_heads = 1;
    claims.arch.d_head = 2;
    claims.arch.d_ff = 6;
    claims.arch.vocab = 8;
    claims.arch.max_context = 8;
    claims.quant.residual_bits = 8;
    claims.quant.residual_exponent = claims
        .quant
        .act_exponents
        .iter()
        .find(|(p, _)| *p == QuantPoint::Embed)
        .unwrap()
        .1;
    claims.quant.rsqrt_kappa = 0;
    claims.quant.exp_sigma = 3;
    for (point, values) in &mut claims.quant.shift_class_sets {
        *values = if matches!(
            point,
            QuantPoint::Layer { site, .. }
                if matches!(
                    site,
                    Site::RopeQ
                        | Site::RopeK
                        | Site::V
                        | Site::AttnResidual
                        | Site::Silu
                        | Site::Up
                        | Site::MlpResidual
                )
        ) {
            shifts.to_vec()
        } else {
            vec![12]
        };
    }
    for (_, scale) in &mut claims.quant.score_scales {
        *scale = tv_codec::Rational::new(1, 1).unwrap();
    }
    claims.gadget_policy.max_log2_rows = max_log2_rows;
    claims.gadget_policy.limb_bits = 8;
    let public = validation::check_public(&claims).unwrap();
    let graph = lowering::lower(&public, 2).unwrap();
    (claims, graph)
}

fn range_specs() -> Vec<TableSpec> {
    (1..=32)
        .map(|bits| {
            GeneratedTable::new(TableId(u32::from(bits)), TableKind::Range { bits })
                .unwrap()
                .spec()
                .clone()
        })
        .collect()
}

fn convert_sc_proof(p: &tessera_sumcheck::SumcheckProof<F>) -> TvScProof {
    TvScProof {
        rounds: p.rounds.iter().map(|r| to_tv_fp2s(r)).collect(),
        final_evals: to_tv_fp2s(&p.final_evals),
    }
}

fn tv_table_from_spec(spec: &TableSpec) -> tv_tables::Table {
    let bytes = encode(spec);
    let decoded = decode(&bytes, &DecodeLimits::MESSAGE, tv_tables::TableSpec::decode).unwrap();
    tv_tables::Table::from_spec(&decoded).unwrap()
}

fn verify_lookups_via_logup(
    lookups: &Lookups<G>,
    tables: &[&GeneratedTable],
    table_cols: &[TableColumns<G>],
) -> Result<(), String> {
    let mults = lookups
        .multiplicities(table_cols)
        .map_err(|e| format!("multiplicities failed: {e}"))?;
    let instances = lookups
        .instances(table_cols, &mults)
        .map_err(|e| format!("instances failed: {e}"))?;
    let (mut pt, mut vt) = fresh_transcripts();
    let tree_ids = TreeId::paired(instances.len());
    let proven = prove_logup::<F, _>(&mut pt, &instances, &[], &tree_ids)
        .map_err(|e| format!("prove_logup failed: {e}"))?;

    let tv_tables: Vec<tv_tables::Table> = lookups
        .groups()
        .iter()
        .map(|g| {
            let spec = tables
                .iter()
                .find(|t| t.spec().id == g.table())
                .unwrap()
                .spec();
            tv_table_from_spec(spec)
        })
        .collect();

    let roots_vec = to_tv_fp2s(proven.roots());
    let roots = tvl::check_roots(&mut vt, instances.len(), &roots_vec)
        .map_err(|e| format!("check_roots failed: {e:?}"))?;
    let heights: Vec<usize> = instances
        .iter()
        .zip(&tv_tables)
        .flat_map(|(inst, tbl)| {
            [
                inst.lookups.len().next_power_of_two().trailing_zeros() as usize,
                usize::from(tbl.log2_rows()),
            ]
        })
        .collect();
    let tallest = heights.iter().copied().max().unwrap_or(0);
    let mut claims: Vec<tvt::LevelClaim> = roots
        .instances
        .iter()
        .flat_map(|r| {
            [
                tvt::LevelClaim::Fraction(r.lookup.clone()),
                tvt::LevelClaim::Fraction(r.table.clone()),
            ]
        })
        .collect();
    for (level, lvl_proof) in proven.levels().iter().enumerate() {
        let present: Vec<usize> = (0..heights.len())
            .filter(|&p| tallest - heights[p] <= level)
            .collect();
        let entering: Vec<tvt::LevelClaim> = present.iter().map(|&p| claims[p].clone()).collect();
        let tv_proof = convert_sc_proof(lvl_proof.proof());
        let checked = tvt::verify_level(&mut vt, level as u32, &entering, &tv_proof)
            .map_err(|e| format!("verify_level {level} failed: {e:?}"))?;
        for (&p, next) in present.iter().zip(&checked.claims) {
            claims[p] = next.clone();
        }
    }
    let fraction = |p: usize| match &claims[p] {
        tvt::LevelClaim::Fraction(c) => c.clone(),
        tvt::LevelClaim::Product(_) => unreachable!(),
    };
    let leaves: Vec<tvl::Leaves> = instances
        .iter()
        .enumerate()
        .map(|(k, inst)| tvl::Leaves {
            lookup: fraction(2 * k),
            table: fraction(2 * k + 1),
            has_values: inst.table.has_values(),
        })
        .collect();
    let values_vec = to_tv_fp2s(proven.values());
    let beta = roots.challenges.beta;
    tvl::check_leaves(
        &mut vt,
        &roots.challenges,
        &leaves,
        &values_vec,
        |i, rho| tv_tables.get(i)?.eval_mle(rho, beta).ok(),
    )
    .map(|_| ())
    .map_err(|e| format!("check_leaves failed: {e:?}"))
}

#[test]
fn requant_honest_and_alternative_witnesses_reject_with_exact_gadget_id() {
    let mut seen_one = false;
    let mut seen_split = false;
    let mut seen_wide = false;
    for (budget, shifts) in [
        (32u8, &[12i8][..]),
        (16u8, &[12i8][..]),
        (24u8, &[1i8][..]),
        (24u8, &[4i8][..]),
        (24u8, &[4i8, 5, 6, 7][..]),
    ] {
        let (claims, graph) = model_with_requant_budget(budget, shifts);
        let selected = tv_core::selection::derive(&graph, claims.gadget_policy).unwrap();
        let plan = Plan::derive(&graph, claims.gadget_policy).unwrap();
        let tv_tables: Vec<GeneratedTable> = selected
            .tables
            .iter()
            .filter_map(|t| {
                let kind = match t.kind {
                    tv_tables::TableKind::Range { bits } => TableKind::Range { bits },
                    tv_tables::TableKind::Requant {
                        b,
                        ref r_by_class,
                        lo,
                        hi,
                    } => TableKind::Requant {
                        b,
                        r_by_class: r_by_class.clone(),
                        lo,
                        hi,
                    },
                    tv_tables::TableKind::Silu {
                        b,
                        ref r_by_class,
                        in_exp,
                        out_exp,
                    } => TableKind::Silu {
                        b,
                        r_by_class: r_by_class.clone(),
                        in_exp,
                        out_exp,
                    },
                    _ => return None,
                };
                Some(GeneratedTable::new(TableId(t.id.0), kind).unwrap())
            })
            .collect();
        let specs: Vec<TableSpec> = tv_tables.iter().map(|t| t.spec().clone()).collect();

        for site in plan.requantizations().map(Result::unwrap) {
            let pattern = site.pattern();
            match pattern {
                TvPattern::Lookup => continue,
                TvPattern::Requant1 => seen_one = true,
                TvPattern::RequantSplit { .. } => seen_split = true,
                TvPattern::RequantWide { .. } => seen_wide = true,
                _ => unreachable!(),
            }
            let table_ids: Vec<TableId> = site.tables().iter().map(|id| TableId(id.0)).collect();
            let compiler_gadget = match pattern {
                TvPattern::Requant1 => Gadget::Requant1 {
                    table: table_ids[0],
                },
                TvPattern::RequantSplit { split } => Gadget::RequantSplit {
                    split,
                    low: table_ids[0],
                    high: table_ids[1],
                },
                TvPattern::RequantWide { split, middle } => {
                    let offset = usize::from(split > 0);
                    Gadget::RequantWide {
                        split,
                        middle,
                        low: (split > 0).then_some(table_ids[0]),
                        mid: table_ids[offset],
                        top: table_ids[offset + 1],
                        sign: table_ids[offset + 2],
                        high: table_ids[offset + 3],
                    }
                }
                _ => unreachable!(),
            };
            let producer = Requant::new(&compiler_gadget, &specs).unwrap();
            let n_vars = (0..=8)
                .find(|&v| site.inputs(&sample_point(v, 1)).is_ok())
                .unwrap();
            let point = sample_point(n_vars, 42 + u64::from(site.gadget().0));
            let len = 1usize << n_vars;
            let n_classes = producer.classes();
            let keys: Vec<i64> = (0..len).map(|i| (i as i64) * 3 - 5).collect();
            let classes: Option<Vec<u8>> =
                (n_classes > 1).then(|| (0..len).map(|i| (i % n_classes) as u8).collect());

            let honest = producer.witness(&keys, classes.as_deref()).unwrap();
            let constraints = producer.constraints::<G>();
            let lookups = Lookups::new(&constraints, &keys, classes.as_deref(), &honest).unwrap();
            let tables = producer.tables();
            let small_tables = tables.iter().all(|t| t.row_count() <= 1 << 12);
            let table_cols: Vec<TableColumns<G>> = if small_tables {
                tables
                    .iter()
                    .map(|t| TableColumns::new(t))
                    .collect::<Result<_, _>>()
                    .unwrap()
            } else {
                Vec::new()
            };
            if small_tables {
                verify_lookups_via_logup(&lookups, &tables, &table_cols)
                    .expect("honest Requant LogUp passes");
            }

            let ch_vars = site
                .inputs(&point)
                .unwrap()
                .nth(2)
                .filter(|_| classes.is_some())
                .map_or(0, |inp| inp.point.len());
            let eval_witness = |w: &tessera_gadgets::Witness| -> Vec<Fp2> {
                let mut vals = vec![
                    eval_mle_i64(&keys, &point),
                    eval_mle_i64(w.tensor(Committed::Y).unwrap(), &point),
                ];
                if let Some(cls) = &classes {
                    let cls_i64: Vec<i64> = cls.iter().map(|&c| i64::from(c)).collect();
                    let ch_cols: Vec<i64> = cls_i64.into_iter().take(1 << ch_vars).collect();
                    vals.push(eval_mle_i64(&ch_cols, &point[..ch_vars]));
                }
                for role in [Committed::ZLo, Committed::H0, Committed::G] {
                    if let Some(col) = w.tensor(role) {
                        vals.push(eval_mle_i64(col, &point));
                    }
                }
                vals
            };

            let honest_values = eval_witness(&honest);
            let read_honest = |term: Term| match term {
                Term::Input => honest_values[0],
                Term::Committed(Committed::Y) => honest_values[1],
                Term::Class => {
                    if classes.is_some() {
                        honest_values[2]
                    } else {
                        Fp2::ZERO
                    }
                }
                Term::Committed(role) => {
                    let mut idx = 2 + usize::from(classes.is_some());
                    for r in [Committed::ZLo, Committed::H0, Committed::G] {
                        if r == role {
                            return honest_values[idx];
                        }
                        if honest.tensor(r).is_some() {
                            idx += 1;
                        }
                    }
                    unreachable!()
                }
            };
            let honest_lookup_evals: Vec<(Fp2, Fp2)> = constraints
                .lookups
                .iter()
                .map(|l| {
                    let eval_affine = |a: &tessera_gadgets::Affine<G>| {
                        a.terms.iter().fold(
                            Fp2::from(to_tv_fp(a.constant)),
                            |acc, &(coeff, term)| {
                                acc + Fp2::from(to_tv_fp(coeff)) * read_honest(term)
                            },
                        )
                    };
                    (
                        eval_affine(&l.key),
                        l.value.as_ref().map_or(Fp2::ZERO, eval_affine),
                    )
                })
                .collect();

            let checked = site
                .check(&point, &honest_values, &honest_lookup_evals)
                .expect("honest Requant check passes");
            assert_eq!(checked.claims().count(), honest_values.len());

            let mut alts = vec![
                RequantAlternative::OutputDelta {
                    index: 0,
                    delta: -1,
                },
                RequantAlternative::OutputDelta { index: 0, delta: 1 },
            ];
            match pattern {
                TvPattern::RequantSplit { .. } => {
                    alts.push(RequantAlternative::SplitLowPlusPow2S { index: 0 });
                    alts.push(RequantAlternative::SplitLowMinusOne { index: 0 });
                }
                TvPattern::RequantWide { split, .. } => {
                    if split > 0 {
                        alts.push(RequantAlternative::SplitLowPlusPow2S { index: 0 });
                        alts.push(RequantAlternative::SplitLowMinusOne { index: 0 });
                    }
                    alts.push(RequantAlternative::WideMiddlePlusPow2T { index: 0 });
                    alts.push(RequantAlternative::WideMiddleMinusOne { index: 0 });
                    alts.push(RequantAlternative::WideSaturationDelta {
                        index: 0,
                        delta: -1,
                    });
                    alts.push(RequantAlternative::WideSaturationDelta { index: 0, delta: 1 });
                }
                _ => {}
            }

            for alt in alts {
                let bad_witness = producer
                    .malicious_witness(&keys, classes.as_deref(), alt)
                    .unwrap();
                if small_tables {
                    let bad_lookups =
                        Lookups::new(&constraints, &keys, classes.as_deref(), &bad_witness)
                            .unwrap();
                    assert!(
                        verify_lookups_via_logup(&bad_lookups, &tables, &table_cols).is_err(),
                        "alternative witness {alt:?} must fail LogUp"
                    );
                }
                let bad_values = eval_witness(&bad_witness);
                let err = site
                    .check(&point, &bad_values, &honest_lookup_evals)
                    .err()
                    .expect("alternative witness must be rejected by Requant::check");
                assert_eq!(
                    err,
                    TvGadgetError::Rejected {
                        gadget: site.gadget()
                    },
                    "wrong rejection for {alt:?}"
                );
            }
        }
    }
    assert!(seen_one && seen_split && seen_wide);

    // Also run full `prove_logup` -> `verify_logup` on small-table `RequantSplit` and
    // `RequantWide` gadgets so every alternative witness perturbation is verified against
    // the independent LogUp verifier as well as `Requant::check`.
    let split_specs = vec![
        GeneratedTable::new(TableId(0), TableKind::Range { bits: 2 })
            .unwrap()
            .spec()
            .clone(),
        GeneratedTable::new(
            TableId(1),
            TableKind::Requant {
                b: 6,
                r_by_class: vec![2, 3],
                lo: -7,
                hi: 7,
            },
        )
        .unwrap()
        .spec()
        .clone(),
    ];
    let split_gadget = Requant::new(
        &Gadget::RequantSplit {
            split: 2,
            low: TableId(0),
            high: TableId(1),
        },
        &split_specs,
    )
    .unwrap();
    let split_keys = [-120i64, -5, 0, 19];
    let split_classes = [0u8, 1, 0, 1];
    let split_tables = split_gadget.tables();
    let split_cols: Vec<TableColumns<G>> = split_tables
        .iter()
        .map(|t| TableColumns::new(t))
        .collect::<Result<_, _>>()
        .unwrap();
    let split_constraints = split_gadget.constraints::<G>();
    let split_honest = split_gadget
        .witness(&split_keys, Some(&split_classes))
        .unwrap();
    let split_lookups = Lookups::new(
        &split_constraints,
        &split_keys,
        Some(&split_classes),
        &split_honest,
    )
    .unwrap();
    verify_lookups_via_logup(&split_lookups, &split_tables, &split_cols)
        .expect("honest RequantSplit LogUp passes");
    for alt in [
        RequantAlternative::OutputDelta {
            index: 0,
            delta: -1,
        },
        RequantAlternative::OutputDelta { index: 0, delta: 1 },
        RequantAlternative::SplitLowPlusPow2S { index: 0 },
        RequantAlternative::SplitLowMinusOne { index: 0 },
    ] {
        let bad = split_gadget
            .malicious_witness(&split_keys, Some(&split_classes), alt)
            .unwrap();
        let bad_lookups =
            Lookups::new(&split_constraints, &split_keys, Some(&split_classes), &bad).unwrap();
        assert!(
            verify_lookups_via_logup(&bad_lookups, &split_tables, &split_cols).is_err(),
            "RequantSplit {alt:?} must fail LogUp"
        );
    }

    let wide_specs = vec![
        GeneratedTable::new(TableId(0), TableKind::Range { bits: 2 })
            .unwrap()
            .spec()
            .clone(),
        GeneratedTable::new(TableId(1), TableKind::Range { bits: 4 })
            .unwrap()
            .spec()
            .clone(),
        GeneratedTable::new(TableId(2), TableKind::Range { bits: 3 })
            .unwrap()
            .spec()
            .clone(),
        GeneratedTable::new(
            TableId(3),
            TableKind::Requant {
                b: 4,
                r_by_class: vec![1],
                lo: -2,
                hi: 1,
            },
        )
        .unwrap()
        .spec()
        .clone(),
        GeneratedTable::new(
            TableId(4),
            TableKind::Requant {
                b: 6,
                r_by_class: vec![1, 2],
                lo: -4,
                hi: 3,
            },
        )
        .unwrap()
        .spec()
        .clone(),
    ];
    let wide_gadget = Requant::new(
        &Gadget::RequantWide {
            split: 2,
            middle: 4,
            low: Some(TableId(0)),
            mid: TableId(1),
            top: TableId(2),
            sign: TableId(3),
            high: TableId(4),
        },
        &wide_specs,
    )
    .unwrap();
    let wide_keys = [-200i64, -15, 0, 180];
    let wide_classes = [0u8, 1, 0, 1];
    let wide_tables = wide_gadget.tables();
    let wide_cols: Vec<TableColumns<G>> = wide_tables
        .iter()
        .map(|t| TableColumns::new(t))
        .collect::<Result<_, _>>()
        .unwrap();
    let wide_constraints = wide_gadget.constraints::<G>();
    let wide_honest = wide_gadget
        .witness(&wide_keys, Some(&wide_classes))
        .unwrap();
    let wide_lookups = Lookups::new(
        &wide_constraints,
        &wide_keys,
        Some(&wide_classes),
        &wide_honest,
    )
    .unwrap();
    verify_lookups_via_logup(&wide_lookups, &wide_tables, &wide_cols)
        .expect("honest RequantWide LogUp passes");
    for alt in [
        RequantAlternative::OutputDelta {
            index: 0,
            delta: -1,
        },
        RequantAlternative::OutputDelta { index: 0, delta: 1 },
        RequantAlternative::SplitLowPlusPow2S { index: 0 },
        RequantAlternative::SplitLowMinusOne { index: 0 },
        RequantAlternative::WideMiddlePlusPow2T { index: 0 },
        RequantAlternative::WideMiddleMinusOne { index: 0 },
        RequantAlternative::WideSaturationDelta {
            index: 0,
            delta: -1,
        },
        RequantAlternative::WideSaturationDelta { index: 0, delta: 1 },
    ] {
        let bad = wide_gadget
            .malicious_witness(&wide_keys, Some(&wide_classes), alt)
            .unwrap();
        let bad_lookups =
            Lookups::new(&wide_constraints, &wide_keys, Some(&wide_classes), &bad).unwrap();
        assert!(
            verify_lookups_via_logup(&bad_lookups, &wide_tables, &wide_cols).is_err(),
            "RequantWide {alt:?} must fail LogUp"
        );
    }
}

#[test]
fn non_neg_honest_and_alternative_witnesses_reject_with_exact_gadget_id() {
    let specs = range_specs();
    let producer = NonNeg::new(20, 8, &specs).unwrap();
    let verifier = TvDecomposition::derive(20, 8).unwrap();
    let gadget_id = GadgetId(7);
    let point = sample_point(2, 300);
    let values = [42i64, 1_025, 65_535, (1 << 20) - 7];

    // 1. Honest witness passes LogUp and TvDecomposition::check.
    let honest = producer.witness(&values).unwrap();
    let constraints = producer.constraints::<G>();
    let lookups = Lookups::new(&constraints, &values, None, &honest).unwrap();
    let tables = producer.tables();
    let table_cols: Vec<TableColumns<G>> = tables
        .iter()
        .map(|t| TableColumns::new(t))
        .collect::<Result<_, _>>()
        .unwrap();
    verify_lookups_via_logup(&lookups, &tables, &table_cols).expect("honest NonNeg LogUp passes");

    let value_eval = eval_mle_i64(&values, &point);
    let eval_low = |w: &tessera_gadgets::Witness| -> Vec<Fp2> {
        (0..producer.limbs() - 1)
            .map(|j| eval_mle_i64(w.tensor(Committed::Limb(j as u8)).unwrap(), &point))
            .collect()
    };
    let honest_low = eval_low(&honest);
    let top_col: Vec<G> = (0..values.len())
        .map(|row| {
            constraints.virtuals[0].1.evaluate(|t| match t {
                Term::Input => G::from_i64(values[row]),
                Term::Committed(role) => G::from_i64(honest.tensor(role).unwrap()[row]),
                Term::Class => G::ZERO,
            })
        })
        .collect();
    let mut honest_keys = honest_low.clone();
    honest_keys.push(eval_mle_fp(&top_col, &point));

    let checked = verifier
        .check(
            gadget_id,
            TvDecompValues {
                point: &point,
                value: value_eval,
                low: &honest_low,
                keys: &honest_keys,
            },
        )
        .expect("honest NonNeg check passes");
    assert_eq!(checked.claims().count(), 4);

    // 2. Alternative witnesses (`v_j + 2^L` with `v_{j+1} - 1`, and `v_j - 1` with `v_{j+1} + 1`).
    for limb_idx in 0..(producer.limbs() - 1) as u8 {
        for alt in [
            NonNegAlternative::LimbPlusPow2L {
                limb: limb_idx,
                index: 1,
            },
            NonNegAlternative::LimbMinusOne {
                limb: limb_idx,
                index: 1,
            },
        ] {
            let bad = producer.malicious_witness(&values, alt).unwrap();
            let bad_lookups = Lookups::new(&constraints, &values, None, &bad).unwrap();
            assert!(
                verify_lookups_via_logup(&bad_lookups, &tables, &table_cols).is_err(),
                "NonNeg alternative {alt:?} must fail LogUp"
            );
            let bad_low = eval_low(&bad);
            let err = verifier
                .check(
                    gadget_id,
                    TvDecompValues {
                        point: &point,
                        value: value_eval,
                        low: &bad_low,
                        keys: &honest_keys,
                    },
                )
                .err()
                .expect("NonNeg alternative must be rejected by Decomposition::check");
            assert_eq!(err, TvGadgetError::Rejected { gadget: gadget_id });
        }
    }
}

#[test]
fn bigint_compare_honest_and_alternative_witnesses_reject_with_exact_gadget_id() {
    let specs = range_specs();
    let bounds_l = [500u64, 500, 0];
    let bounds_r = [500u64, 500, 0];
    let producer = BigIntCompare::new(8, &bounds_l, &bounds_r, &specs).unwrap();
    let verifier = TvComparison::derive(8, &bounds_l, &bounds_r).unwrap();
    let gadget_id = GadgetId(19);
    let point = sample_point(2, 400);

    let left_cols = [
        vec![300i64, 10, 255, 0],
        vec![100i64, 20, 1, 0],
        vec![0i64; 4],
    ];
    let right_cols = [
        vec![310i64, 20, 255, 1],
        vec![105i64, 20, 2, 0],
        vec![0i64; 4],
    ];
    let left_refs: Vec<&[i64]> = left_cols.iter().map(Vec::as_slice).collect();
    let right_refs: Vec<&[i64]> = right_cols.iter().map(Vec::as_slice).collect();

    // 1. Honest witness passes LogUp and TvComparison::check.
    let honest = producer.witness(&left_refs, &right_refs).unwrap();
    let constraints = producer.constraints::<G>().unwrap();
    let eval_arrays = |w: &tessera_gadgets::CompareWitness| -> [Vec<Fp2>; 6] {
        std::array::from_fn(|a| {
            (0..producer.limbs())
                .map(|j| {
                    let col = match a {
                        0 => CompareColumn::Digit(Side::Left, j),
                        1 => CompareColumn::Carry(Side::Left, j),
                        2 => CompareColumn::Digit(Side::Right, j),
                        3 => CompareColumn::Carry(Side::Right, j),
                        4 => CompareColumn::Difference(j),
                        5 => CompareColumn::Borrow(j),
                        _ => unreachable!(),
                    };
                    eval_mle_i64(w.tensor(col).unwrap(), &point)
                })
                .collect()
        })
    };
    let left_evals: Vec<Fp2> = left_cols.iter().map(|c| eval_mle_i64(c, &point)).collect();
    let right_evals: Vec<Fp2> = right_cols.iter().map(|c| eval_mle_i64(c, &point)).collect();
    let honest_arrays = eval_arrays(&honest);
    let checked = verifier
        .check(
            gadget_id,
            TvCompareValues {
                point: &point,
                left: &left_evals,
                right: &right_evals,
                arrays: honest_arrays.each_ref().map(Vec::as_slice),
            },
        )
        .expect("honest BigIntCompare check passes");
    assert_eq!(checked.claims().count(), 8 * producer.limbs());

    let tables: Vec<&GeneratedTable> = producer.tables().iter().collect();
    let table_cols: Vec<TableColumns<G>> = tables
        .iter()
        .map(|t| TableColumns::new(t))
        .collect::<Result<_, _>>()
        .unwrap();
    let compare_lookups = |w: &tessera_gadgets::CompareWitness| -> Lookups<G> {
        let cols = constraints
            .lookups
            .iter()
            .map(|lookup| {
                let (_, col) = lookup.key.terms[0];
                let keys: SecretBuf<G> = w
                    .tensor(col)
                    .unwrap()
                    .iter()
                    .map(|&v| G::from_i64(v))
                    .collect();
                (lookup.table, keys, None)
            })
            .collect();
        lookups_from_columns(cols).unwrap()
    };
    verify_lookups_via_logup(&compare_lookups(&honest), &tables, &table_cols)
        .expect("honest BigIntCompare LogUp passes");

    // 2a. False comparison `X > Y` (both with honest final borrow `1` and with cleared final borrow `0`).
    for clear_final_borrow in [false, true] {
        let bad = producer
            .malicious_witness(
                &right_refs,
                &left_refs,
                CompareAlternative::FalseComparison { clear_final_borrow },
            )
            .unwrap();
        let bad_arrays = eval_arrays(&bad);
        let err = verifier
            .check(
                gadget_id,
                TvCompareValues {
                    point: &point,
                    left: &right_evals,
                    right: &left_evals,
                    arrays: bad_arrays.each_ref().map(Vec::as_slice),
                },
            )
            .err()
            .expect("X > Y must be rejected by TvComparison::check");
        assert_eq!(err, TvGadgetError::Rejected { gadget: gadget_id });
    }

    // 2b. Digit/carry shift (`d_j + 2^L, c_j - 1` and `d_j - 1, c_j + 1`).
    for side in [Side::Left, Side::Right] {
        for add_radix in [true, false] {
            let alt = CompareAlternative::DigitCarryShift {
                side,
                limb: 0,
                row: 0,
                add_radix,
            };
            let bad = producer
                .malicious_witness(&left_refs, &right_refs, alt)
                .unwrap();
            assert!(
                verify_lookups_via_logup(&compare_lookups(&bad), &tables, &table_cols).is_err(),
                "DigitCarryShift {alt:?} must fail LogUp"
            );
            let bad_arrays = eval_arrays(&bad);
            let err = verifier
                .check(
                    gadget_id,
                    TvCompareValues {
                        point: &point,
                        left: &left_evals,
                        right: &right_evals,
                        arrays: bad_arrays.each_ref().map(Vec::as_slice),
                    },
                )
                .err()
                .expect("DigitCarryShift must be rejected by TvComparison::check");
            assert_eq!(err, TvGadgetError::Rejected { gadget: gadget_id });
        }
    }
}

#[test]
fn softmax_honest_and_alternative_witnesses_reject_with_exact_gadget_id() {
    let mut claims = base_claims();
    claims.arch.d_model = 2;
    claims.arch.n_heads = 1;
    claims.arch.n_kv_heads = 1;
    claims.arch.d_head = 2;
    claims.arch.d_ff = 6;
    claims.arch.vocab = 8;
    claims.arch.max_context = 8;
    claims.quant.residual_bits = 8;
    claims.quant.residual_exponent = claims
        .quant
        .act_exponents
        .iter()
        .find(|(p, _)| *p == QuantPoint::Embed)
        .unwrap()
        .1;
    claims.quant.rsqrt_kappa = 0;
    claims.quant.exp_sigma = 4;
    for (_, scale) in &mut claims.quant.score_scales {
        *scale = tv_codec::Rational::new(1, 1).unwrap();
    }
    claims.gadget_policy.max_log2_rows = 32;
    claims.gadget_policy.limb_bits = 8;
    let public = validation::check_public(&claims).unwrap();
    let graph = lowering::lower(&public, 3).unwrap();
    let selected = tv_core::selection::derive(&graph, claims.gadget_policy).unwrap();
    let plan = Plan::derive(&graph, claims.gadget_policy).unwrap();
    let site = plan.softmaxes().next().unwrap().unwrap();
    let gadget_id = site.gadget();

    let mut specs: Vec<TableSpec> = selected
        .tables
        .iter()
        .filter_map(|t| {
            let kind = match t.kind {
                tv_tables::TableKind::Range { bits } => TableKind::Range { bits },
                tv_tables::TableKind::Exp {
                    key_bits,
                    sigma,
                    scale,
                } => TableKind::Exp {
                    key_bits,
                    sigma,
                    scale: Rational::new(scale.num(), scale.den()).unwrap(),
                },
                _ => return None,
            };
            Some(
                GeneratedTable::new(TableId(t.id.0), kind)
                    .unwrap()
                    .spec()
                    .clone(),
            )
        })
        .collect();
    let exp_id = specs
        .iter()
        .find(|s| matches!(s.kind, TableKind::Exp { .. }))
        .unwrap()
        .id;
    let _ = &mut specs;
    let producer = SoftmaxRow::new(exp_id, 8, 8, &specs).unwrap();
    let tables = producer.tables();
    let table_cols: Vec<TableColumns<G>> = tables
        .iter()
        .map(|t| TableColumns::new(t))
        .collect::<Result<_, _>>()
        .unwrap();

    let row_scores: [[i64; 4]; 4] = [[5, 9, 2, 11], [4, 8, 3, 12], [7, 1, 6, 10], [0, 0, 0, 0]];
    let valids = [1usize, 2, 3, 0];

    let build_columns = |alt: Option<(usize, SoftmaxAlternative)>| {
        let mut witnesses = Vec::new();
        let mut evaluations = Vec::new();
        for r in 0..4 {
            let (w, ev) = match alt {
                Some((target_row, a)) if target_row == r => {
                    let w = producer
                        .malicious_witness(&row_scores[r], valids[r], a)
                        .unwrap();
                    let ev = producer
                        .malicious_evaluate::<G>(&row_scores[r], valids[r], &w, a)
                        .unwrap();
                    (w, ev)
                }
                _ => {
                    let w = producer.witness(&row_scores[r], valids[r]).unwrap();
                    let ev = producer
                        .evaluate::<G>(&row_scores[r], valids[r], &w)
                        .unwrap();
                    (w, ev)
                }
            };
            witnesses.push(w);
            evaluations.push(ev);
        }
        (witnesses, evaluations)
    };

    let (honest_w, honest_ev) = build_columns(None);
    for ev in &honest_ev {
        verify_lookups_via_logup(&ev.lookups, &tables, &table_cols)
            .expect("honest Softmax row LogUp passes");
    }

    let check_forest_row = |ev: &tessera_gadgets::SoftmaxEvaluation<G>| -> Result<(), String> {
        let (mut pt, mut vt) = fresh_transcripts();
        let proven = prove_forests::<F, _>(&mut pt, &[Forest::new(&ev.leaves, 2)])
            .map_err(|e| format!("prove_forests: {e}"))?;
        let mut claims = vec![tvt::TreeClaim {
            point: vec![],
            value: Fp2::from(to_tv_fp(ev.root)),
        }];
        for (level, p) in proven.levels().iter().enumerate() {
            let tv_proof = convert_sc_proof(p.proof());
            claims = tvt::verify_product_level(&mut vt, level as u32, &claims, &tv_proof)
                .map_err(|e| format!("verify_product_level {level}: {e:?}"))?
                .claims;
        }
        if claims[0].value != eval_mle_fp(&ev.leaves, &claims[0].point) {
            return Err("product leaf mismatch".into());
        }
        Ok(())
    };
    for ev in &honest_ev {
        check_forest_row(ev).expect("honest Softmax product forest passes");
    }

    let row_point = sample_point(site.row_variables(), 500);
    let full_point = sample_point(site.variables(), 501);
    let sum_point = site.row_sum_point(&row_point).unwrap();

    let eval_softmax_row_claims = |ws: &[tessera_gadgets::SoftmaxWitness],
                                   evs: &[tessera_gadgets::SoftmaxEvaluation<G>]|
     -> (Vec<Fp2>, Vec<Fp2>, Vec<Fp2>) {
        let recip_col: Vec<i64> = ws
            .iter()
            .map(|w| w.tensor(SoftmaxColumn::Reciprocal).unwrap()[0])
            .collect();
        let exp_col: Vec<i64> = ws
            .iter()
            .flat_map(|w| {
                w.tensor(SoftmaxColumn::Exponentials)
                    .unwrap()
                    .iter()
                    .copied()
            })
            .collect();
        let mut sources = vec![
            eval_mle_i64(&recip_col, &row_point),
            eval_mle_i64(&exp_col, &sum_point),
        ];
        let lows = (producer.constraints::<G>().committed.len() - 3) / 2;
        for slack in [Slack::A, Slack::B] {
            for j in 0..lows {
                let limb_col: Vec<i64> = ws
                    .iter()
                    .map(|w| w.tensor(SoftmaxColumn::Limb(slack, j as u8)).unwrap()[0])
                    .collect();
                sources.push(eval_mle_i64(&limb_col, &row_point));
            }
        }
        let num_range_lookups = site.range_tables().len();
        let mut keys = Vec::with_capacity(num_range_lookups);
        let constraints = producer.constraints::<G>();
        for l_idx in 1..constraints.lookups.len() {
            let col: Vec<G> = (0..4)
                .map(|r| {
                    let score_sum: G = ws[r]
                        .tensor(SoftmaxColumn::Exponentials)
                        .unwrap()
                        .iter()
                        .fold(G::ZERO, |a, &x| a + G::from_i64(x));
                    let psi = G::from_u64_reduced(u64::from(valids[r] != 0));
                    let recip = G::from_i64(ws[r].tensor(SoftmaxColumn::Reciprocal).unwrap()[0]);
                    let a = psi * G::from_u64_reduced(producer.mass_bound()) - recip * score_sum;
                    let b = score_sum - psi - a;
                    constraints.lookups[l_idx].key.evaluate(|t| match t {
                        tessera_gadgets::SoftmaxTerm::Column(c) => {
                            G::from_i64(ws[r].tensor(c).unwrap()[0])
                        }
                        tessera_gadgets::SoftmaxTerm::Virtual(
                            tessera_gadgets::SoftmaxValue::Slack(Slack::A),
                        ) => a,
                        tessera_gadgets::SoftmaxTerm::Virtual(
                            tessera_gadgets::SoftmaxValue::Slack(Slack::B),
                        ) => b,
                        _ => G::ZERO,
                    })
                })
                .collect();
            keys.push(eval_mle_fp(&col, &row_point));
        }
        let values = vec![Fp2::ZERO; keys.len()];
        let _ = evs;
        (sources, keys, values)
    };

    let (honest_sources, honest_keys, honest_values) =
        eval_softmax_row_claims(&honest_w, &honest_ev);
    let _checked = site
        .check(&row_point, &honest_sources, &honest_keys, &honest_values)
        .expect("honest Softmax::check passes");

    let softmax_alts = [
        (1usize, SoftmaxAlternative::MaskedLeavesZero),
        (
            1usize,
            SoftmaxAlternative::MaskedLeavesRealKeys {
                masked_max: Some(12),
            },
        ),
        (2usize, SoftmaxAlternative::SecondLargestMax),
        (2usize, SoftmaxAlternative::MaxPlusOne),
        (2usize, SoftmaxAlternative::ReciprocalDelta(-1)),
        (2usize, SoftmaxAlternative::ReciprocalDelta(1)),
        (
            3usize,
            SoftmaxAlternative::PaddedNonZero {
                column: SoftmaxColumn::Maximum,
                value: 5,
            },
        ),
        (
            3usize,
            SoftmaxAlternative::PaddedNonZero {
                column: SoftmaxColumn::Reciprocal,
                value: 5,
            },
        ),
    ];

    for (target_row, alt) in softmax_alts {
        let (bad_w, bad_ev) = build_columns(Some((target_row, alt)));
        match alt {
            SoftmaxAlternative::MaskedLeavesZero
            | SoftmaxAlternative::MaskedLeavesRealKeys { .. } => {
                let leaf_col: Vec<G> = bad_ev
                    .iter()
                    .flat_map(|ev| ev.leaves.iter().copied())
                    .collect();
                let leaf_eval = eval_mle_fp(&leaf_col, &full_point);
                let tree_key = site.tree(&full_point, leaf_eval).unwrap();
                let err = tree_key
                    .evaluate(&full_point, &[Fp2::ZERO])
                    .err()
                    .expect("malformed tree evaluation count must reject");
                assert_eq!(err, TvGadgetError::Rejected { gadget: gadget_id });
                let honest_leaf_col: Vec<G> = honest_ev
                    .iter()
                    .flat_map(|ev| ev.leaves.iter().copied())
                    .collect();
                assert_ne!(
                    eval_mle_fp(&honest_leaf_col, &full_point),
                    leaf_eval,
                    "{alt:?} must change the leaf polynomial at full_point"
                );
            }
            SoftmaxAlternative::SecondLargestMax => {
                assert!(
                    verify_lookups_via_logup(&bad_ev[target_row].lookups, &tables, &table_cols)
                        .is_err(),
                    "SecondLargestMax must fail Exp LogUp"
                );
                let (bad_sources, _, _) = eval_softmax_row_claims(&bad_w, &bad_ev);
                let err = site
                    .check(&row_point, &bad_sources, &honest_keys, &honest_values)
                    .err()
                    .expect("SecondLargestMax must be rejected by Softmax::check");
                assert_eq!(err, TvGadgetError::Rejected { gadget: gadget_id });
            }
            SoftmaxAlternative::MaxPlusOne => {
                assert!(
                    check_forest_row(&bad_ev[target_row]).is_err(),
                    "MaxPlusOne must fail product forest root check"
                );
                let (bad_sources, _, _) = eval_softmax_row_claims(&bad_w, &bad_ev);
                let err = site
                    .check(&row_point, &bad_sources, &honest_keys, &honest_values)
                    .err()
                    .expect("MaxPlusOne must be rejected by Softmax::check");
                assert_eq!(err, TvGadgetError::Rejected { gadget: gadget_id });
            }
            SoftmaxAlternative::ReciprocalDelta(_) => {
                assert!(
                    verify_lookups_via_logup(&bad_ev[target_row].lookups, &tables, &table_cols)
                        .is_err(),
                    "{alt:?} must fail slack Range LogUp"
                );
                let (bad_sources, _, _) = eval_softmax_row_claims(&bad_w, &bad_ev);
                let err = site
                    .check(&row_point, &bad_sources, &honest_keys, &honest_values)
                    .err()
                    .expect("ReciprocalDelta must be rejected by Softmax::check");
                assert_eq!(err, TvGadgetError::Rejected { gadget: gadget_id });
            }
            SoftmaxAlternative::PaddedNonZero { column, .. } => {
                assert!(
                    bad_ev[target_row].padding.iter().any(|&v| v != G::ZERO),
                    "{alt:?} must produce a non-zero padding check entry"
                );
                let kind = if column == SoftmaxColumn::Maximum {
                    TvSoftmaxPadding::Maximum
                } else {
                    TvSoftmaxPadding::Reciprocal
                };
                let col_vals: SecretBuf<G> = bad_w
                    .iter()
                    .map(|w| G::from_i64(w.tensor(column).unwrap()[0]))
                    .collect();
                let zero_pt = [
                    F::from(G::from_u64_reduced(7)),
                    F::from(G::from_u64_reduced(13)),
                ];
                let eq_z: Vec<F> = (0..4).map(|r| eq_ext(&zero_pt, r)).collect();
                let one_minus_psi: Vec<G> = (0..4)
                    .map(|r| G::from_u64_reduced(u64::from(valids[r] == 0)))
                    .collect();
                let sc_inst = ScInstance::sum_of_products(
                    vec![
                        ScTable::ext(&eq_z).public(),
                        ScTable::base(&one_minus_psi).public(),
                        ScTable::base(&col_vals),
                    ],
                    vec![ScTerm::new(F::ONE, vec![0, 1, 2])],
                );
                let (mut pt, mut vt) = fresh_transcripts();
                let proven = prove_batch(&mut pt, ScPrefix::Stage(1), 3, &[sc_inst]).unwrap();
                let tv_zero: Vec<Fp2> = zero_pt.iter().copied().map(to_tv_fp2).collect();
                let tv_inst = site.padding_instance();
                let tv_proof = convert_sc_proof(proven.proof());
                let res = verify_batch(
                    &mut vt,
                    TvScPrefix::Stage(1),
                    3,
                    &[tv_inst],
                    &tv_proof,
                    |_, pt_eval, vals| {
                        site.padding(kind, &tv_zero, pt_eval, vals)
                            .ok()
                            .map(|f| f.value())
                    },
                );
                assert!(
                    res.is_err(),
                    "{alt:?} must fail padding sumcheck verification"
                );
                let err = site
                    .padding(kind, &tv_zero, &row_point, &[])
                    .err()
                    .expect("Softmax::padding count mismatch must reject");
                assert_eq!(err, TvGadgetError::Rejected { gadget: gadget_id });
            }
        }
    }
}

#[test]
fn rsqrt_honest_and_alternative_witnesses_reject_with_exact_gadget_id() {
    let mut claims = base_claims();
    claims.arch.d_model = 4;
    claims.arch.n_heads = 1;
    claims.arch.n_kv_heads = 1;
    claims.arch.d_head = 4;
    claims.arch.d_ff = 6;
    claims.arch.vocab = 8;
    claims.arch.max_context = 8;
    claims.quant.residual_bits = 8;
    claims.quant.residual_exponent = claims
        .quant
        .act_exponents
        .iter()
        .find(|(p, _)| *p == QuantPoint::Embed)
        .unwrap()
        .1;
    claims.quant.rsqrt_kappa = 4;
    claims.quant.rms_eps_int = 3;
    claims.quant.exp_sigma = 3;
    for (_, s) in &mut claims.quant.shift_class_sets {
        *s = vec![12];
    }
    for (_, s) in &mut claims.quant.score_scales {
        *s = tv_codec::Rational::new(1, 1).unwrap();
    }
    let public = validation::check_public(&claims).unwrap();
    let graph = lowering::lower(&public, 3).unwrap();
    let plan = Plan::derive(&graph, claims.gadget_policy).unwrap();
    let site = plan.roots().next().unwrap().unwrap();
    let gadget_id = site.gadget();

    let specs = range_specs();
    let producer = RsqrtRow::new(4, 4, 3, &specs).unwrap();
    let squares = [10i64, 25, 60, 0];
    let real = [true, true, true, false];
    let u: Vec<i64> = squares
        .iter()
        .zip(&real)
        .map(|(&s, &act)| if act { s + 3 } else { 0 })
        .collect();
    let point = sample_point(2, 600);

    let eval_root_witness = |w: &tessera_gadgets::RsqrtWitness| -> (Vec<Fp2>, Vec<Fp2>, Vec<Fp2>) {
        let constraints = producer.constraints::<G>().unwrap();
        let mut sources = vec![
            eval_mle_i64(&squares, &point),
            eval_mle_i64(w.tensor(RsqrtColumn::Root).unwrap(), &point),
        ];
        for &col in &constraints.committed[1..] {
            sources.push(eval_mle_i64(w.tensor(col).unwrap(), &point));
        }
        let keys: Vec<Fp2> = constraints
            .lookups
            .iter()
            .map(|lookup| {
                let col: Vec<G> = (0..4)
                    .map(|row| {
                        lookup.key.evaluate(|t| match t {
                            tessera_gadgets::RsqrtTerm::Input => G::from_i64(u[row]),
                            tessera_gadgets::RsqrtTerm::RowSelector => {
                                G::from_u64_reduced(u64::from(real[row]))
                            }
                            tessera_gadgets::RsqrtTerm::Column(c) => {
                                G::from_i64(w.tensor(c).unwrap()[row])
                            }
                        })
                    })
                    .collect();
                eval_mle_fp(&col, &point)
            })
            .collect();
        let values = vec![Fp2::ZERO; keys.len()];
        (sources, keys, values)
    };

    // 1. Honest witness passes Root::check.
    let honest = producer.witness(&u, &real).unwrap();
    let (honest_sources, honest_keys, honest_values) = eval_root_witness(&honest);
    let _checked = site
        .check(&point, &honest_sources, &honest_keys, &honest_values)
        .expect("honest Root::check passes");

    // 2a. RootDelta (`ρ - 1` and `ρ + 1`, with `clear_final_borrow` false and true) rejects
    //     directly in `Root::check` with `GadgetError::Rejected { gadget }` and exact `gadget_id`!
    for delta in [-1i64, 1] {
        for clear_final_borrow in [false, true] {
            let alt = RsqrtAlternative::RootDelta {
                row: 0,
                delta,
                clear_final_borrow,
            };
            let bad = producer.malicious_witness(&u, &real, alt).unwrap();
            let (bad_sources, bad_keys, bad_values) = eval_root_witness(&bad);
            let err = site
                .check(&point, &bad_sources, &bad_keys, &bad_values)
                .err()
                .expect("RootDelta must be rejected by Root::check");
            assert_eq!(
                err,
                TvGadgetError::Rejected { gadget: gadget_id },
                "wrong rejection for {alt:?}"
            );
        }
    }

    // 2b. PaddedRoot (nonzero root on padded row 3):
    let padded_alt = RsqrtAlternative::PaddedRoot { row: 3, root: 7 };
    let bad_padded = producer.malicious_witness(&u, &real, padded_alt).unwrap();
    let (bad_padded_sources, _, _) = eval_root_witness(&bad_padded);
    let err = site
        .check(&point, &bad_padded_sources, &honest_keys, &honest_values)
        .err()
        .expect("PaddedRoot must be rejected by Root::check against honest keys");
    assert_eq!(err, TvGadgetError::Rejected { gadget: gadget_id });

    let root_col: SecretBuf<G> = bad_padded
        .tensor(RsqrtColumn::Root)
        .unwrap()
        .iter()
        .map(|&v| G::from_i64(v))
        .collect();
    let zero_pt = [
        F::from(G::from_u64_reduced(5)),
        F::from(G::from_u64_reduced(11)),
    ];
    let eq_z: Vec<F> = (0..4).map(|r| eq_ext(&zero_pt, r)).collect();
    let one_minus_psi: Vec<G> = (0..4)
        .map(|r| G::from_u64_reduced(u64::from(!real[r])))
        .collect();
    let sc_inst = ScInstance::sum_of_products(
        vec![
            ScTable::ext(&eq_z).public(),
            ScTable::base(&one_minus_psi).public(),
            ScTable::base(&root_col),
        ],
        vec![ScTerm::new(F::ONE, vec![0, 1, 2])],
    );
    let (mut pt, mut vt) = fresh_transcripts();
    let proven = prove_batch(&mut pt, ScPrefix::Stage(1), 3, &[sc_inst]).unwrap();
    let tv_zero: Vec<Fp2> = zero_pt.iter().copied().map(to_tv_fp2).collect();
    let tv_inst = site.padding_instance();
    let tv_proof = convert_sc_proof(proven.proof());
    let res = verify_batch(
        &mut vt,
        TvScPrefix::Stage(1),
        3,
        &[tv_inst],
        &tv_proof,
        |_, pt_eval, vals| {
            site.padding(&tv_zero, pt_eval, vals)
                .ok()
                .map(|f| f.value())
        },
    );
    assert!(
        res.is_err(),
        "PaddedRoot must fail the mandatory padded-root sumcheck"
    );
}

#[test]
fn onehot_honest_and_alternative_witnesses_reject_with_exact_gadget_id() {
    let mut claims = base_claims();
    claims.arch.vocab = 6;
    claims.arch.max_context = 8;
    let public = validation::check_public(&claims).unwrap();
    let graph = lowering::lower(&public, 2).unwrap();
    let plan = Plan::derive(&graph, claims.gadget_policy).unwrap();
    let site = plan.one_hots().next().unwrap().unwrap();
    let gadget_id = site.gadget();

    let producer = OneHot::<G>::new(6).unwrap();
    let padded = producer.padded_len();
    assert_eq!(padded, 8);
    let tokens = [3i64, 0];

    let run_onehot_stage = |row0: &tessera_gadgets::OneHotWitness<G>| -> Result<(), String> {
        let row1 = producer.witness(tokens[1], true).unwrap();
        let mut h = SecretBuf::with_capacity(16);
        h.extend(row0.indicator().iter().copied());
        h.extend(row1.indicator().iter().copied());

        let row_pt = [F::from(G::from_u64_reduced(19))];
        let tv_row_pt = [to_tv_fp2(row_pt[0])];
        let token_col = [G::from_i64(tokens[0]), G::from_i64(tokens[1])];
        let token_eval = eval_mle_fp(&token_col, &tv_row_pt);
        let at = site.at(&tv_row_pt, token_eval).unwrap();

        let dummy_pt = sample_point(4, 700);
        let err = at
            .evaluate(TvOneHotRelation::Booleanity, &dummy_pt, &dummy_pt, &[])
            .err()
            .unwrap();
        assert_eq!(err, TvGadgetError::Rejected { gadget: gadget_id });

        let zero_pt = [
            F::from(G::from_u64_reduced(3)),
            F::from(G::from_u64_reduced(7)),
            F::from(G::from_u64_reduced(11)),
            F::from(G::from_u64_reduced(13)),
        ];
        let tv_zero_pt: Vec<Fp2> = zero_pt.iter().copied().map(to_tv_fp2).collect();
        let full_eq: Vec<F> = (0..16).map(|r| eq_ext(&zero_pt, r)).collect();
        let row_eq: Vec<F> = (0..16).map(|r| eq_ext(&row_pt, r / padded)).collect();
        let valid: Vec<G> = (0..16)
            .map(|r| G::from_u64_reduced(u64::from(r % padded < 6)))
            .collect();
        let indices: Vec<G> = (0..16)
            .map(|r| G::from_u64_reduced((r % padded) as u64))
            .collect();

        let instances = [
            ScInstance::sum_of_products(
                vec![ScTable::ext(&full_eq).public(), ScTable::base(&h)],
                vec![
                    ScTerm::new(F::ONE, vec![0, 1]),
                    ScTerm::new(-F::ONE, vec![0, 1, 1]),
                ],
            ),
            ScInstance::sum_of_products(
                vec![
                    ScTable::ext(&full_eq).public(),
                    ScTable::base(&valid).public(),
                    ScTable::base(&h),
                ],
                vec![
                    ScTerm::new(F::ONE, vec![0, 2]),
                    ScTerm::new(-F::ONE, vec![0, 1, 2]),
                ],
            ),
            ScInstance::sum_of_products(
                vec![ScTable::ext(&row_eq).public(), ScTable::base(&h)],
                vec![ScTerm::new(F::ONE, vec![0, 1])],
            ),
            ScInstance::sum_of_products(
                vec![
                    ScTable::ext(&row_eq).public(),
                    ScTable::base(&indices).public(),
                    ScTable::base(&h),
                ],
                vec![ScTerm::new(F::ONE, vec![0, 1, 2])],
            ),
        ];

        let (mut pt, mut vt) = fresh_transcripts();
        let proven =
            prove_batch(&mut pt, ScPrefix::Stage(1), 3, &instances).map_err(|e| format!("{e}"))?;
        let tv_instances: Vec<TvScInstance> =
            site.relations().map(|rel| at.instance(rel)).collect();
        let tv_proof = convert_sc_proof(proven.proof());
        let relations: Vec<TvOneHotRelation> = site.relations().collect();
        verify_batch(
            &mut vt,
            TvScPrefix::Stage(1),
            3,
            &tv_instances,
            &tv_proof,
            |i, pt_eval, vals| {
                at.evaluate(relations[i], &tv_zero_pt, pt_eval, vals)
                    .ok()
                    .map(|f| f.value())
            },
        )
        .map(|_| ())
        .map_err(|e| format!("{e:?}"))
    };

    // 1. Honest OneHot witness verifies:
    let honest = producer.witness(tokens[0], true).unwrap();
    run_onehot_stage(&honest).expect("honest OneHot witness verifies");

    // 2. Alternative witnesses from RFC-0009 Lemma 8 / 07 §4 all fail verification:
    for alt in [
        OneHotAlternative::TwoOnes {
            first: 1,
            second: 2,
        },
        OneHotAlternative::WrongIndex { index: 4 },
        OneHotAlternative::PaddedVocabularyOne { index: 6 },
        OneHotAlternative::NonBoolean { index: 3, value: 2 },
    ] {
        let bad = producer.malicious_witness(alt).unwrap();
        assert!(
            run_onehot_stage(&bad).is_err(),
            "OneHot alternative {alt:?} must be rejected"
        );
    }
}

#[test]
fn argmax_honest_and_alternative_witnesses_reject_with_exact_gadget_id() {
    let range = GeneratedTable::new(TableId(29), TableKind::Range { bits: 29 }).unwrap();
    let vocab = 6usize;
    let padded = 8usize;
    let producer = Argmax::<G>::new(vocab, range.spec()).unwrap();
    let onehot = OneHot::<G>::new(vocab).unwrap();
    let gadget_id = GadgetId(99);
    let site = TvArgmax::derive(gadget_id, vocab as u32, 1).unwrap();

    let logits: Vec<G> = [3i64, 15, 9, 12, 15, 4, 0, 0]
        .into_iter()
        .map(G::from_i64)
        .collect();
    let honest_token = 1i64;

    let check_argmax = |next: &tessera_gadgets::OneHotWitness<G>,
                        argmax_w: &tessera_gadgets::ArgmaxWitness<G>,
                        ev: &tessera_gadgets::ArgmaxEvaluation<G>|
     -> Result<(), String> {
        for &k in ev.keys.iter() {
            let signed = i64::try_from(k.to_centered_i128()).map_err(|_| "key overflow")?;
            if range.lookup(signed, 0) != Some(0) {
                return Err(format!("Range(29) membership failed for key {signed}"));
            }
        }

        let key_pt = [
            F::from(G::from_u64_reduced(5)),
            F::from(G::from_u64_reduced(9)),
            F::from(G::from_u64_reduced(13)),
        ];
        let tv_key_pt: Vec<Fp2> = key_pt.iter().copied().map(to_tv_fp2).collect();
        let tv_row_pt: [Fp2; 0] = [];

        let key_claim = eval_mle_fp(&ev.keys, &tv_key_pt);
        let max_claim = Fp2::from(to_tv_fp(argmax_w.maximum()[0]));

        let key_rel = site.lookup(&tv_key_pt, key_claim, Fp2::ZERO).unwrap();
        let sel_rel = site.selected(&tv_row_pt, max_claim).unwrap();

        let key_eq: Vec<F> = (0..padded).map(|i| eq_ext(&key_pt, i)).collect();
        let valid: Vec<G> = (0..padded)
            .map(|i| G::from_u64_reduced(u64::from(i < vocab)))
            .collect();
        let max_broadcast: SecretBuf<G> = (0..padded).map(|_| argmax_w.maximum()[0]).collect();

        let instances = [
            ScInstance::sum_of_products(
                vec![
                    ScTable::ext(&key_eq).public(),
                    ScTable::base(&valid).public(),
                    ScTable::base(&max_broadcast),
                    ScTable::base(&logits),
                    ScTable::base(&ev.suffix),
                ],
                vec![
                    ScTerm::new(F::ONE, vec![0, 1, 2]),
                    ScTerm::new(-F::ONE, vec![0, 1, 3]),
                    ScTerm::new(-F::ONE, vec![0, 1, 4]),
                ],
            ),
            ScInstance::sum_of_products(
                vec![ScTable::base(next.indicator()), ScTable::base(&logits)],
                vec![ScTerm::new(F::ONE, vec![0, 1])],
            ),
        ];

        let (mut pt, mut vt) = fresh_transcripts();
        let proven1 =
            prove_batch(&mut pt, ScPrefix::Stage(1), 3, &instances).map_err(|e| format!("{e}"))?;
        let tv_proof1 = convert_sc_proof(proven1.proof());
        let batch1 = verify_batch(
            &mut vt,
            TvScPrefix::Stage(1),
            3,
            &[key_rel.instance(), sel_rel.instance()],
            &tv_proof1,
            |i, pt_eval, vals| {
                if i == 0 {
                    key_rel.evaluate(pt_eval, vals).ok().map(|f| f.value())
                } else {
                    sel_rel.evaluate(pt_eval, vals).ok().map(|f| f.value())
                }
            },
        )
        .map_err(|e| format!("stage 1 verify_batch: {e:?}"))?;

        let suffix_rel = site
            .suffix(&batch1.point, tv_proof1.final_evals[2])
            .unwrap();
        let kernel: Vec<F> = (0..padded)
            .map(|i| {
                let bits: [F; 3] =
                    std::array::from_fn(|b| F::from(G::from_u64_reduced(((i >> b) & 1) as u64)));
                tessera_gadgets::suffix_kernel(proven1.point(), &bits).unwrap()
            })
            .collect();
        let inst2 = [ScInstance::sum_of_products(
            vec![
                ScTable::ext(&kernel).public(),
                ScTable::base(next.indicator()),
            ],
            vec![ScTerm::new(F::ONE, vec![0, 1])],
        )];
        let proven2 =
            prove_batch(&mut pt, ScPrefix::Stage(2), 2, &inst2).map_err(|e| format!("{e}"))?;
        let tv_proof2 = convert_sc_proof(proven2.proof());
        verify_batch(
            &mut vt,
            TvScPrefix::Stage(2),
            2,
            &[suffix_rel.instance()],
            &tv_proof2,
            |_, pt_eval, vals| suffix_rel.evaluate(pt_eval, vals).ok().map(|f| f.value()),
        )
        .map(|_| ())
        .map_err(|e| format!("stage 2 verify_batch: {e:?}"))
    };

    // 1. Honest Argmax witness verifies:
    let honest_next = onehot.witness(honest_token, true).unwrap();
    let honest_argmax = producer.witness(&logits, true).unwrap();
    let honest_ev = producer
        .evaluate(&logits, &honest_next, &honest_argmax)
        .unwrap();
    check_argmax(&honest_next, &honest_argmax, &honest_ev).expect("honest Argmax witness verifies");

    // 2. Alternative witnesses (`LaterTie` at index 4, `MaxDelta(-1)`, `MaxDelta(1)`):
    for alt in [
        ArgmaxAlternative::LaterTie { later_index: 4 },
        ArgmaxAlternative::MaxDelta(-1),
        ArgmaxAlternative::MaxDelta(1),
    ] {
        let (bad_next, bad_argmax, bad_ev) = producer
            .malicious_evaluate(&logits, true, honest_token, alt)
            .unwrap();
        assert!(
            check_argmax(&bad_next, &bad_argmax, &bad_ev).is_err(),
            "Argmax alternative {alt:?} must fail verification"
        );
    }

    // 3. Direct `tv_core::gadgets::argmax::Argmax` final-check rejections carry `GadgetId`:
    let sample_pt = sample_point(3, 800);
    assert_eq!(
        site.lookup(&sample_pt, Fp2::ZERO, Fp2::ONE).err(),
        Some(TvGadgetError::Rejected { gadget: gadget_id })
    );
    let key_rel = site.lookup(&sample_pt, Fp2::ZERO, Fp2::ZERO).unwrap();
    assert_eq!(
        key_rel.evaluate(&sample_pt, &[Fp2::ZERO]).err(),
        Some(TvGadgetError::Rejected { gadget: gadget_id })
    );
    let sel_rel = site.selected(&[], Fp2::ZERO).unwrap();
    assert_eq!(
        sel_rel.evaluate(&sample_pt, &[Fp2::ZERO]).err(),
        Some(TvGadgetError::Rejected { gadget: gadget_id })
    );
    let suf_rel = site.suffix(&sample_pt, Fp2::ZERO).unwrap();
    assert_eq!(
        suf_rel.evaluate(&sample_pt, &[]).err(),
        Some(TvGadgetError::Rejected { gadget: gadget_id })
    );
}

#[test]
fn malicious_witness_generator_hook_is_compiled_out_of_release_builds() {
    let lib_rs = include_str!("../../tessera-gadgets/src/lib.rs");
    assert!(
        lib_rs.contains("#[cfg(debug_assertions)]\npub mod malicious;"),
        "tessera-gadgets must gate `pub mod malicious` behind `#[cfg(debug_assertions)]` so release builds omit it"
    );
}
